 private void overview(){heading("Your Velixio","A little more personal. Exactly how you like to watch.");row("◈","Appearance",themeName()+" · "+(prefs.getBoolean("compactPosters",false)?"Compact posters":"Comfortable posters"),()->navigate("appearance"));row("▷","Playback","Quality, autoplay and playback speed",()->navigate("playback"));row("↥","Your data","Back up, restore and manage your collection",()->navigate("data"));row("↻","App updates","Check, download and install from GitHub",()->startActivity(new Intent(this,UpdatesActivity.class)));label("Made for your collection");TextView footer=Ui.text(this,"Your list and viewing history stay on this device. Take them with you using a Velixio backup.",13,Ui.MUTED);footer.setLineSpacing(dp(3),1);body.addView(footer);TextView version=Ui.text(this,"VELIXIO  /  1.0.2",11,Ui.MUTED);version.setLetterSpacing(.15f);version.setPadding(0,dp(32),0,dp(8));body.addView(version);}
 private String themeName(){return ThemePalette.NAMES[ThemePalette.index(prefs.getInt("theme",0))];}
 private void appearance(){heading("Set the mood","Choose your palette. Make room for more stories.");label("Color palette");String[] names=ThemePalette.NAMES;String[] descriptions=ThemePalette.DESCRIPTIONS;int[] accents=new int[names.length],surfaces=new int[names.length];for(int n=0;n<names.length;n++){accents[n]=ThemePalette.COLORS[n][1];surfaces[n]=ThemePalette.COLORS[n][2];}
  GridLayout palette=new GridLayout(this);int paletteColumns=getResources().getConfiguration().screenWidthDp>=360&&getResources().getConfiguration().fontScale<=1.3f?2:1;palette.setColumnCount(paletteColumns);body.addView(palette);for(int i=0;i<names.length;i++){final int theme=i;boolean selected=prefs.getInt("theme",0)==i;LinearLayout c=card();body.removeView(c);GridLayout.LayoutParams paletteTile=new GridLayout.LayoutParams();paletteTile.width=0;paletteTile.height=-2;paletteTile.columnSpec=GridLayout.spec(i%paletteColumns,1f);paletteTile.rowSpec=GridLayout.spec(i/paletteColumns);paletteTile.setMargins(0,0,dp(8),dp(8));palette.addView(c,paletteTile);GradientDrawable border=shape(surfaces[i],18);if(selected)border.setStroke(dp(2),accents[i]);c.setBackground(border);LinearLayout preview=new LinearLayout(this);preview.setPadding(0,0,0,dp(12));for(int tile=0;tile<3;tile++){View sample=new View(this);GradientDrawable art=new GradientDrawable(GradientDrawable.Orientation.TL_BR,new int[]{accents[i],surfaces[i]});art.setCornerRadius(dp(8));sample.setBackground(art);sample.setAlpha(1f-tile*.22f);LinearLayout.LayoutParams sampleSpace=new LinearLayout.LayoutParams(0,dp(tile==0?68:52),1);sampleSpace.rightMargin=dp(6);sampleSpace.gravity=Gravity.BOTTOM;preview.addView(sample,sampleSpace);}c.addView(preview);LinearLayout line=new LinearLayout(this);line.setGravity(Gravity.CENTER_VERTICAL);View swatch=new View(this);swatch.setBackground(shape(accents[i],16));LinearLayout.LayoutParams sw=new LinearLayout.LayoutParams(dp(32),dp(32));sw.rightMargin=dp(14);TextView name=Ui.text(this,names[i],17,Ui.INK);name.setTypeface(null,Typeface.BOLD);line.addView(name,new LinearLayout.LayoutParams(0,-2,1));line.addView(Ui.text(this,selected?"✓":"",20,accents[i]));c.addView(line);TextView caption=Ui.text(this,descriptions[i],13,Ui.MUTED);caption.setPadding(0,dp(8),0,0);c.addView(caption);c.setFocusable(true);c.setContentDescription(names[i]+(selected?", selected":""));c.setOnClickListener(v->{prefs.edit().putInt("theme",theme).apply();render();});}
  label("Poster layout");choice("Comfortable","Larger artwork, more breathing room",!prefs.getBoolean("compactPosters",false),()->{prefs.edit().putBoolean("compactPosters",false).apply();render();});choice("Compact","More titles visible at a glance",prefs.getBoolean("compactPosters",false),()->{prefs.edit().putBoolean("compactPosters",true).apply();render();});
 }
 private void choice(String title,String subtitle,boolean selected,Runnable action){LinearLayout c=card();c.setOrientation(LinearLayout.HORIZONTAL);c.setGravity(Gravity.CENTER_VERTICAL);LinearLayout copy=Ui.column(this);copy.setBackgroundColor(Color.TRANSPARENT);copy.addView(Ui.text(this,title,22,Ui.INK));if(!subtitle.isEmpty())copy.addView(Ui.text(this,subtitle,13,Ui.MUTED));c.addView(copy,new LinearLayout.LayoutParams(0,-2,1));TextView check=Ui.text(this,selected?"●":"○",22,selected?Ui.ACCENT:Ui.MUTED);check.setPadding(dp(16),0,0,0);c.addView(check);c.setMinimumHeight(dp(64));c.setFocusable(true);c.setContentDescription(title+(selected?", selected":""));c.setOnClickListener(v->action.run());}
 private void toggle(String title,String description,String key,boolean initial){LinearLayout c=card();c.setOrientation(LinearLayout.HORIZONTAL);c.setGravity(Gravity.CENTER_VERTICAL);LinearLayout copy=Ui.column(this);copy.setBackgroundColor(Color.TRANSPARENT);copy.addView(Ui.text(this,title,22,Ui.INK));copy.addView(Ui.text(this,description,13,Ui.MUTED));c.addView(copy,new LinearLayout.LayoutParams(0,-2,1));Switch control=new Switch(this);control.setContentDescription(title);control.setChecked(prefs.getBoolean(key,initial));control.setPadding(dp(16),0,0,0);control.setMinimumHeight(dp(48));control.setOnCheckedChangeListener((v,value)->prefs.edit().putBoolean(key,value).apply());c.addView(control);}
 private void playback(){heading("Press play. Unwind.","Your defaults, ready for the next movie night.");toggle("Autoplay next episode","Keep the story going when an episode ends.","autoplay",false);toggle("Remember speed","Use your last playback speed next time.","rememberSpeed",true);label("Preferred video quality");String[] names={"Automatic","Data saver","HD","Full HD","Highest available"};String[] details={"Let the player adapt to the connection","Up to 480p","Up to 720p","Up to 1080p","Use the best quality the stream offers"};int[] heights={0,480,720,1080,-1};for(int i=0;i<names.length;i++){final int value=heights[i];choice(names[i],details[i],prefs.getInt("qualityHeight",0)==value,()->{prefs.edit().putInt("qualityHeight",value).apply();render();});}body.addView(Ui.text(this,"Available quality, audio and captions vary by title. You can change them while watching.",13,Ui.MUTED));}
 private void data(){heading("Your stories, saved.","Keep your collection close. Take it with you.");LinearLayout stats=card();int saved=getSharedPreferences("favorites",0).getAll().size(),watched=getSharedPreferences("watch-history",0).getAll().size();stats.addView(Ui.text(this,saved+" saved titles",24,Ui.INK));stats.addView(Ui.text(this,watched+" titles in your viewing history",14,Ui.MUTED));label("Back up & restore");row("◷","Automatic backups",getSharedPreferences("auto-backup",0).getString("folder","").isEmpty()?"Choose a folder once, then back up daily":"Daily backups are enabled",()->navigate("backup"));row("↥","Export your collection","Save a .velixiodata backup to your chosen location",()->{if(!busy)startActivityForResult(new Intent(Intent.ACTION_CREATE_DOCUMENT).addCategory(Intent.CATEGORY_OPENABLE).setType("application/octet-stream").putExtra(Intent.EXTRA_TITLE,"Velixio-"+new java.text.SimpleDateFormat("yyyy-MM-dd",java.util.Locale.ROOT).format(new java.util.Date())+".velixiodata"),40);});row("↧","Restore a backup","Review its contents before importing",()->{if(!busy)startActivityForResult(new Intent(Intent.ACTION_OPEN_DOCUMENT).addCategory(Intent.CATEGORY_OPENABLE).setType("*/*"),41);});body.addView(Ui.text(this,"Includes My list, watch history, playback positions and preferences. Backups contain viewing metadata, not video files. Store them somewhere you trust.",13,Ui.MUTED));label("Manage history");row("↺","Clear watch history","Remove watched titles and saved playback positions",()->{if(!busy)navigate("clear");});}
 private void backup(){heading("A little peace of mind","Automatic daily backups to a folder you choose. Your latest seven copies are kept when the folder allows cleanup.");android.content.SharedPreferences b=getSharedPreferences("auto-backup",0);boolean enabled=!b.getString("folder","").isEmpty();LinearLayout status=card();status.addView(Ui.text(this,enabled?"Automatic backups are on":"Choose where to save",21,Ui.INK));long last=b.getLong("lastSuccess",0);status.addView(Ui.text(this,last==0?"No automatic backup yet":"Last saved · "+java.text.DateFormat.getDateTimeInstance(java.text.DateFormat.MEDIUM,java.text.DateFormat.SHORT).format(new java.util.Date(last)),13,Ui.MUTED));if(b.contains("error"))status.addView(Ui.text(this,b.getString("error",""),13,0xffffb4a8));Button choose=Ui.primary(this,enabled?"Change backup folder":"Choose backup folder");choose.setOnClickListener(v->startActivityForResult(new Intent(Intent.ACTION_OPEN_DOCUMENT_TREE).addFlags(Intent.FLAG_GRANT_READ_URI_PERMISSION|Intent.FLAG_GRANT_WRITE_URI_PERMISSION|Intent.FLAG_GRANT_PERSISTABLE_URI_PERMISSION),42));body.addView(choose);if(enabled){Button now=Ui.chip(this,"Back up now");now.setOnClickListener(v->execute("Saving automatic backup…",()->{AutoBackup.write(this,true);return true;},value->{render();message("Backup saved",false);}));body.addView(now);Button stop=Ui.quiet(this,"Turn off automatic backups");stop.setOnClickListener(v->execute("Turning off backups…",()->{AutoBackup.stop(this);return true;},value->{render();message("Automatic backups are off. Existing copies are kept.",false);}));body.addView(stop);}body.addView(Ui.text(this,"Includes your saved list, watch history and preferences, not downloaded videos. Android schedules the daily backup; timing may vary with battery restrictions. A cloud-backed folder syncs only if its provider supports it.",13,Ui.MUTED));}
 private void clearPage(){heading("A fresh start?","Clear watch history and saved playback positions on this device. Your saved list and preferences will stay.");Button cancel=Ui.primary(this,"Keep my history");cancel.setOnClickListener(v->navigate("data"));body.addView(cancel);Button clear=Ui.quiet(this,"Clear watch history");clear.setOnClickListener(v->{WatchHistory.clear(this);navigate("data");message("Watch history cleared",false);});body.addView(clear);}
 private void review(){if(pendingImport==null){page="data";data();return;}heading("Ready to restore","Review this backup before adding it to your Velixio.");LinearLayout summary=card();summary.addView(Ui.text(this,pendingImport.optJSONArray("favorites").length()+" saved titles",24,Ui.INK));summary.addView(Ui.text(this,pendingImport.optJSONArray("history").length()+" history entries",16,Ui.MUTED));body.addView(Ui.text(this,"Saved lists are merged. Newer history is retained. Matching playback positions and preferences are replaced by the backup.",14,Ui.MUTED));Button restore=Ui.primary(this,"Restore collection");restore.setOnClickListener(v->{try{VelixioData.restore(this,pendingImport);pendingImport=null;navigate("data");message("Your collection has been restored",false);}catch(Exception e){message("This backup could not be restored. Your collection may exceed the supported limit.",true);}});body.addView(restore);Button cancel=Ui.quiet(this,"Cancel");cancel.setOnClickListener(v->{pendingImport=null;navigate("data");});body.addView(cancel);}
 private void message(String text,boolean error){notice.setTextColor(error?0xffffb4a8:Ui.ACCENT);notice.setText(text);notice.setVisibility(View.VISIBLE);final TextView shown=notice;final CharSequence message=text;if(!busy&&!error)shown.postDelayed(()->{if(!busy&&shown.getText().equals(message))shown.setVisibility(View.GONE);},2200);}
 private interface Task{Object run()throws Exception;}
 private interface Done{void accept(Object result)throws Exception;}
 private void execute(String label,Task task,Done done){if(busy)return;busy=true;message(label,false);worker.submit(()->{try{Object result=task.run();runOnUiThread(()->{if(isDestroyed()||isFinishing())return;busy=false;try{done.accept(result);}catch(Exception e){message("Could not complete this action. Please retry.",true);}});}catch(Exception e){runOnUiThread(()->{if(!isDestroyed()&&!isFinishing()){busy=false;message("Could not complete this action. Check the selected file or folder and try again.",true);}});}});}
 @Override protected void onActivityResult(int request,int result,Intent data){super.onActivityResult(request,result,data);if(result!=RESULT_OK||data==null||data.getData()==null)return;if(request==42){android.net.Uri folder=data.getData();try{int grants=data.getFlags()&(Intent.FLAG_GRANT_READ_URI_PERMISSION|Intent.FLAG_GRANT_WRITE_URI_PERMISSION);if(grants!=(Intent.FLAG_GRANT_READ_URI_PERMISSION|Intent.FLAG_GRANT_WRITE_URI_PERMISSION))throw new SecurityException();getContentResolver().takePersistableUriPermission(folder,Intent.FLAG_GRANT_READ_URI_PERMISSION|Intent.FLAG_GRANT_WRITE_URI_PERMISSION);page="backup";render();execute("Setting up automatic backups…",()->{AutoBackup.configure(this,folder.toString());AutoBackup.write(this,true);return true;},value->{render();message("Automatic backups are ready",false);});}catch(Exception e){message("This folder cannot keep backup access. Choose another folder.",true);}return;}page="data";render();android.net.Uri uri=data.getData();if(request==40)execute("Saving your backup…",()->{byte[] bytes=VelixioData.export(this).toString().getBytes(java.nio.charset.StandardCharsets.UTF_8);try(OutputStream out=getContentResolver().openOutputStream(uri,"wt")){if(out==null)throw new IOException();out.write(bytes);}return true;},value->message("Backup saved. Your collection is ready to take with you.",false));else if(request==41)execute("Reading your backup…",()->{try(InputStream in=getContentResolver().openInputStream(uri)){if(in==null)throw new IOException();return VelixioData.validate(app.veyra.data.CatalogBackend.read(in,VelixioData.LIMIT));}},value->{pendingImport=(JSONObject)value;navigate("review");});}
 @Override public void finish(){setResult(RESULT_OK);super.finish();}
 @Override public void onBackPressed(){if(page.equals("settings")){finish();return;}if(page.equals("review")){pendingImport=null;navigate("data");}else if(page.equals("clear")||page.equals("backup"))navigate("data");else navigate("settings");}
 @Override protected void onSaveInstanceState(Bundle out){out.putString("page",page);super.onSaveInstanceState(out);}
 @Override public Object onRetainNonConfigurationInstance(){return pendingImport;}
 @Override protected void onDestroy(){worker.shutdownNow();super.onDestroy();}
